// ZTechAI - Website HTML Optimizer
// n8n Code Node
// Mode: Run Once for All Items

const MAX_CHARS = 6000;

function extractTitle(html) {
  const match = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (!match) return '';

  return match[1]
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .trim();
}

function extractMetaDescription(html) {
  const match = html.match(
    /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i
  );

  return match ? match[1].trim() : '';
}

function cleanHtml(html) {
  let text = html;

  // Remove unnecessary HTML elements
  text = text
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, '')
    .replace(/<svg\b[^>]*>[\s\S]*?<\/svg>/gi, '')
    .replace(/<iframe\b[^>]*>[\s\S]*?<\/iframe>/gi, '')
    .replace(/<canvas\b[^>]*>[\s\S]*?<\/canvas>/gi, '')
    .replace(/<!--[\s\S]*?-->/g, '');

  // Remove navigation and footer
  text = text
    .replace(/<nav\b[^>]*>[\s\S]*?<\/nav>/gi, '')
    .replace(/<footer\b[^>]*>[\s\S]*?<\/footer>/gi, '')
    .replace(/<header\b[^>]*>[\s\S]*?<\/header>/gi, '');

  // Create readable line breaks
  text = text
    .replace(/<\/(p|div|section|article|main|h1|h2|h3|h4|h5|li)>/gi, '\n')
    .replace(/<(br|hr)\s*\/?>/gi, '\n');

  // Remove remaining HTML tags
  text = text.replace(/<[^>]+>/g, ' ');

  // Decode common entities
  text = text
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');

  // Clean whitespace
  text = text
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();

  return text;
}

function removeNoise(text) {
  const lines = text
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean);

  const noisePatterns = [
    /^cookie/i,
    /accept cookies/i,
    /privacy policy/i,
    /terms of service/i,
    /terms and conditions/i,
    /^login$/i,
    /^sign in$/i,
    /^sign up$/i,
    /^subscribe$/i,
    /^menu$/i,
    /^search$/i,
    /^home$/i,
    /^copyright/i,
    /all rights reserved/i,
    /enable javascript/i
  ];

  const seen = new Set();
  const useful = [];

  for (const line of lines) {
    if (line.length < 3) continue;

    if (noisePatterns.some(pattern => pattern.test(line))) {
      continue;
    }

    const normalized = line
      .toLowerCase()
      .replace(/\s+/g, ' ')
      .trim();

    if (seen.has(normalized)) continue;

    seen.add(normalized);
    useful.push(line);
  }

  return useful.join('\n');
}

function limitText(text, maxChars) {
  if (text.length <= maxChars) return text;

  let shortened = text.substring(0, maxChars);

  const lastNewLine = shortened.lastIndexOf('\n');

  const lastSentence = Math.max(
    shortened.lastIndexOf('. '),
    shortened.lastIndexOf('! '),
    shortened.lastIndexOf('? ')
  );

  const cutPoint = Math.max(lastNewLine, lastSentence);

  if (cutPoint > maxChars * 0.75) {
    shortened = shortened.substring(0, cutPoint + 1);
  }

  return shortened.trim() +
    '\n[Website content truncated for efficiency]';
}

return items.map(item => {

  // Find the HTML from the HTTP Request node
  const html =
    item.json.body ||
    item.json.data ||
    item.json.html ||
    item.json.content ||
    item.json.response ||
    '';

  if (!html || typeof html !== 'string') {
    return {
      json: {
        website_text: '',
        website_title: '',
        website_description: '',
        optimization_status: 'No HTML content found'
      }
    };
  }

  const title = extractTitle(html);
  const description = extractMetaDescription(html);

  let cleaned = cleanHtml(html);
  cleaned = removeNoise(cleaned);

  let finalText = '';

  if (title) {
    finalText += `BUSINESS / WEBSITE TITLE:\n${title}\n\n`;
  }

  if (description) {
    finalText += `WEBSITE DESCRIPTION:\n${description}\n\n`;
  }

  finalText += `EXTRACTED WEBSITE CONTENT:\n${cleaned}`;

  finalText = limitText(finalText, MAX_CHARS);

  // IMPORTANT:
  // Only return the optimized data.
  // The original multi-MB HTML is NOT passed forward.
  return {
    json: {
      website_title: title,
      website_description: description,
      website_text: finalText,
      website_text_length: finalText.length,
      optimization_status: 'HTML extracted and optimized'
    }
  };
});

