// n8n Code node
// Extract ONLY actual external business website URLs
// from raw Google Maps HTML / scraped response.
//
// Output:
// {
//   "website": "https://example.com"
// }
//
// If Google Maps returned no business website in the scraped
// response, this node returns NO items.

const inputItems = $input.all();

const blockedDomains = [
  // Google
  'google.com',
  'google.co.uk',
  'google.ca',
  'google.com.au',
  'google.co.in',
  'google.co.uk',
  'google.de',
  'google.fr',
  'google.es',
  'google.it',
  'google.com.pk',
  'googleapis.com',
  'gstatic.com',
  'googleusercontent.com',
  'googleadservices.com',
  'google-analytics.com',
  'googletagmanager.com',
  'googletravel.com',
  'googlevideo.com',

  // Google Maps infrastructure
  'maps.google.com',
  'maps.googleapis.com',
  'maps.gstatic.com',
  'lh3.googleusercontent.com',

  // Social networks
  'facebook.com',
  'fb.com',
  'instagram.com',
  'linkedin.com',
  'twitter.com',
  'x.com',
  'tiktok.com',
  'youtube.com',
  'youtu.be',
  'pinterest.com',
  'snapchat.com',

  // Common directories / marketplaces
  'yelp.com',
  'tripadvisor.com',
  'yellowpages.com',
  'foursquare.com',
  'mapquest.com',
  'bbb.org',
  'angi.com',
  'homeadvisor.com',
  'thumbtack.com',
  'trustpilot.com',
  'wikipedia.org'
];

function isBlocked(hostname) {
  hostname = hostname.toLowerCase().replace(/^www\./, '');

  return blockedDomains.some(domain =>
    hostname === domain || hostname.endsWith('.' + domain)
  );
}

function cleanUrl(raw) {

  if (!raw || typeof raw !== 'string') {
    return null;
  }

  let url = raw.trim();

  // Decode common HTML entities
  url = url
    .replace(/&amp;/gi, '&')
    .replace(/\\u003d/gi, '=')
    .replace(/\\u0026/gi, '&')
    .replace(/\\u002f/gi, '/')
    .replace(/&quot;/gi, '"');

  // Remove surrounding characters
  url = url.replace(/^[("'`<\[]+/, '');
  url = url.replace(/[)"'`>\],;]+$/, '');

  // Only HTTP/HTTPS
  if (!/^https?:\/\//i.test(url)) {
    return null;
  }

  let parsed;

  try {
    parsed = new URL(url);
  } catch {
    return null;
  }

  // Only normal web URLs
  if (
    parsed.protocol !== 'http:' &&
    parsed.protocol !== 'https:'
  ) {
    return null;
  }

  const hostname = parsed.hostname
    .toLowerCase()
    .replace(/^www\./, '');

  // Must have a real domain
  if (!hostname || !hostname.includes('.')) {
    return null;
  }

  // Reject IP addresses
  if (/^\d{1,3}(\.\d{1,3}){3}$/.test(hostname)) {
    return null;
  }

  // Reject Google and other non-business domains
  if (isBlocked(hostname)) {
    return null;
  }

  // Reject obvious Google paths
  const fullUrl = parsed.href.toLowerCase();

  if (
    fullUrl.includes('google.com/') ||
    fullUrl.includes('googleapis.com/') ||
    fullUrl.includes('gstatic.com/') ||
    fullUrl.includes('googleusercontent.com/') ||
    fullUrl.includes('/maps/')
  ) {
    return null;
  }

  // Remove tracking parameters
  const trackingParameters = [
    'utm_source',
    'utm_medium',
    'utm_campaign',
    'utm_term',
    'utm_content',
    'gclid',
    'fbclid',
    'msclkid'
  ];

  for (const parameter of trackingParameters) {
    parsed.searchParams.delete(parameter);
  }

  // Remove fragment
  parsed.hash = '';

  // Return clean URL
  let result = parsed.toString();

  // Remove trailing slash for root domain
  if (parsed.pathname === '/' && !parsed.search) {
    result = `${parsed.protocol}//${parsed.hostname}`;
  }

  return result;
}


// ----------------------------------------------------
// Extract URLs from all incoming data
// ----------------------------------------------------

const candidates = [];

function scan(value) {

  if (value === null || value === undefined) {
    return;
  }

  if (typeof value === 'string') {

    // Find HTTP/HTTPS URLs.
    const matches = value.match(
      /https?:\/\/[^\s"'<>\\]+/gi
    );

    if (matches) {
      candidates.push(...matches);
    }

    return;
  }

  if (Array.isArray(value)) {

    for (const element of value) {
      scan(element);
    }

    return;
  }

  if (typeof value === 'object') {

    for (const key of Object.keys(value)) {
      scan(value[key]);
    }
  }
}


// Scan every incoming n8n item
for (const item of inputItems) {
  scan(item.json);
}


// ----------------------------------------------------
// Clean + filter + deduplicate
// ----------------------------------------------------

const websites = [];

for (const candidate of candidates) {

  const website = cleanUrl(candidate);

  if (!website) {
    continue;
  }

  websites.push(website);
}

const uniqueWebsites = [...new Set(websites)];


// ----------------------------------------------------
// Return ONLY website field
// ----------------------------------------------------

return uniqueWebsites.map(website => ({
  json: {
    website
  }
}));

