const normalizePhone = (phone) => {
  if (!phone) return '';
  return String(phone).replace(/\D/g, '');
};

const phoneToFind = normalizePhone(
  $('Set all Credentials').first().json['Caller phone']
);

const bookings = $input.first().json.data || [];
const now = new Date();

const matchingBookings = bookings.filter(booking => {

  // Ignore cancelled/rejected bookings
  if (booking.status !== 'accepted') {
    return false;
  }

  // Ignore past bookings
  if (!booking.start || new Date(booking.start) <= now) {
    return false;
  }

  // Match phone number
  return (booking.attendees || []).some(attendee =>
    normalizePhone(attendee.phoneNumber) === phoneToFind
  );
});

return matchingBookings.map(booking => {
  const attendee = (booking.attendees || []).find(
    attendee =>
      normalizePhone(attendee.phoneNumber) === phoneToFind
  );

  return {
    json: {
      id: booking.id,
      uid: booking.uid,
      status: booking.status,
      start: booking.start,
      end: booking.end,
      phoneNumber: attendee?.phoneNumber || '',
      name: attendee?.name || '',
      eventTypeId: booking.eventTypeId
    }
  };
});

